function z({registerIndicator:F,sourceValues:v,nulls:W}){F({id:"oa-bbwn",name:"Bollinger Band Width Normalized (BBWN)",category:"Volatility",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:20,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"},{key:"multiplier",type:"number",label:"StdDev Multiplier",default:2,min:.001,max:100,step:.1},{key:"lookback",type:"number",label:"Lookback Period",default:252,min:1,max:5e3,step:1,tooltip:"Window of past band widths the current width is rescaled against."}],plots:[{key:"bbwn",type:"line",title:"BBWN",style:{color:"#ffeb3b",lineWidth:2}}],calc(b,n){const V=Math.max(1,Math.floor(Number(n.period)||20)),g=Math.max(.001,Number(n.multiplier)||2),A=Math.max(1,Math.floor(Number(n.lookback)||252)),y=v(b,n.source??"close"),k=new Array(b.length).fill(NaN),w=Math.max(1,V),x=new Array(w).fill(NaN);let r=0,e=0,d=0,f=0;const M=Math.max(1,A),p=new Array(M).fill(NaN);let s=0,c=0,t=NaN,u=NaN;for(let i=0;i<b.length;i++){const m=x[r];Number.isFinite(m)&&(d-=m,f-=m*m,e-=1);const l=Number.isFinite(y[i])?y[i]:0;d+=l,f+=l*l,e+=1,x[r]=l,r=(r+1)%w;const B=e>0?d/e:l,S=e>0?f/e-B*B:0,a=2*(e>1?g*Math.sqrt(Math.max(0,S)):0),q=p[s];if(Number.isFinite(q)&&(c-=1),Number.isFinite(a)&&(c+=1),p[s]=a,s=(s+1)%M,c>=1){t=a,u=a;for(let h=0;h<c;h++){const o=p[h];Number.isFinite(o)&&(o<t&&(t=o),o>u&&(u=o))}}const N=u-t;k[i]=Number.isFinite(N)&&N>0?(a-t)/N:.5}return{bbwn:W(k)}}})}export{z as default};
